#!/bin/sh
# Generated by `re-check lab --write` from book.toml, the chapters' steps and examples/stack.toml. Don't edit by hand.
# Checks your work: each check, or every check of a chapter, says Passed or Not yet.
set -eu
book_dir=$(cd "$(dirname "$0")/.." && pwd)
slug=k3s-sampler
stack=k3s
lab_home="${RE_LAB_HOME:-$HOME/.rolling-edition/$slug}"
work="$lab_home/work"
bin="$lab_home/bin"

say() { printf '%s\n' "$*"; }
fail() { printf '%s\n' "$*" >&2; exit 1; }

steps_bash() {
  for b in "$(command -v bash)" /opt/homebrew/bin/bash /usr/local/bin/bash; do
    [ -x "$b" ] && "$b" -c '[ "${BASH_VERSINFO[0]}" -ge 4 ]' 2>/dev/null && { printf '%s\n' "$b"; return 0; }
  done
  command -v bash || fail "The book's steps run with bash: install it, then run this again."
}
bash_bin=$(steps_bash)

check_info() {
  case "$1" in
    shop-namespace-exists) expect=0; hint='Create the namespace first: kubectl create namespace shop' ;;
    web-has-three-replicas) expect=0; hint='Apply the deployment, then wait until its three pods are Running: kubectl -n shop get pods' ;;
    web-has-five-replicas) expect=0; hint='Scale the deployment to five copies, then wait until they'"'"'re available: kubectl -n shop get deployment web' ;;
    home-page-answers) expect=0; hint='Expose the deployment and forward its port in another tab, then try again' ;;
    *) return 1 ;;
  esac
}
chapter_checks() {
  case "$1" in
    first-deployment) echo 'shop-namespace-exists web-has-three-replicas' ;;
    scale-and-serve) echo 'web-has-five-replicas home-page-answers' ;;
    *) return 1 ;;
  esac
}
[ $# -gt 0 ] || fail "Usage: lab/check.sh CHECK_ID or CHAPTER_ID ... The checks: shop-namespace-exists, web-has-three-replicas, web-has-five-replicas, home-page-answers"
[ -d "$work" ] || fail "Run lab/start.sh first."
[ ! -f "$lab_home/kubeconfig" ] || export KUBECONFIG="$lab_home/kubeconfig"
case "$PWD/" in "$work"/*) here="$PWD" ;; *) here="$work" ;; esac
status=0
for given in "$@"; do
  ids=$(chapter_checks "$given" || echo "$given")
  for id in $ids; do
    check_info "$id" || fail "There's no check $id."
    if (cd "$here" && env NO_COLOR=1 TZ=UTC PATH="$bin:$PATH" "$bash_bin" "$book_dir/examples/$id.sh") > "$lab_home/last-check.log" 2>&1
    then code=0; else code=$?; fi
    if [ "$code" -eq "$expect" ]; then say "Passed: $id"
    else say "Not yet: $id.${hint:+ $hint}"; status=1; fi
  done
done
exit $status
